def chart(slug):
 if slug==SLUGS[0]:
  monthly=D[slug]['monthly'];labels=sorted(set(x['month'] for x in monthly)); vals=[sum(r['net_sales'] for r in monthly if r['month']==m) for m in labels]
  top=max(vals);bars=''.join(f'<rect x="{i*28+7}" y="{108-v/top*95:.2f}" width="18" height="{v/top*95:.2f}" rx="2" fill="{("#335a40" if i==len(vals)-1 else "#8fa880")}"/>' for i,v in enumerate(vals))
  return f'<svg viewBox="0 0 315 120" role="img" aria-label="Monthly net sales, January to November 2011">{bars}</svg>'
 if slug==SLUGS[1]:
  rows=D[slug]['forecasts'];days=sorted(set(x['date'] for x in rows));actual=[sum(x['actual'] for x in rows if x['date']==dt) for dt in days];forecast=[sum(x['selected'] for x in rows if x['date']==dt) for dt in days];mx=max(actual+forecast)
  return '<svg viewBox="0 0 315 120" role="img" aria-label="Actual and forecast unit sales over November 2011">'+''.join(f'<polyline points="'+ ' '.join(f'{i*10.6:.2f},{110-v/mx*95:.2f}' for i,v in enumerate(a))+f'" fill="none" stroke="{color}" stroke-width="2.5"/>' for a,color in [(actual,'#b6a58e'),(forecast,'#6c502e')])+'</svg>'
 rows=D[slug]['thresholds'];return '<svg viewBox="0 0 315 120" role="img" aria-label="Precision and recall across decision thresholds">'+''.join('<polyline points="'+' '.join(f'{i*17:.2f},{110-r[k]*95:.2f}' for i,r in enumerate(rows))+f'" fill="none" stroke="{color}" stroke-width="2.5"/>' for k,color in [('precision','#385c59'),('recall','#94aeaa')])+'</svg>'

